package wire

import (
	"encoding/hex"
	"testing"
)

// TestCreateJoinReplyGolden pins the full 0x3200 and 0x3201 replies byte for byte. The want values were produced by v0.2.16, the last
// version a real PS3 hosted Terraria on without freezing (v0.2.17/v0.2.18 froze it). Changing either reply must be deliberate: prove the
// new bytes on hardware, then update the constant.
func TestCreateJoinReplyGolden(t *testing.T) {
	key := []byte("session-key-16by")
	tok := []byte("room-token-16byt")
	rid := [4]byte{0, 0, 0, 7}
	me := MemberInfo{No: 1, Name: "PS3Test", Country: "pt", Addr: []byte{37, 228, 205, 125}, NAT: 2}
	rd := RoomData{WorldID: 1, MaxSlot: 8}
	create := Reply(key, 0x3200, 0, rid, CreateJoinRoomReply(0x0001aaaabbbbcccc, rd, me, tok, tok)...)
	join := Reply(key, 0x3201, 0, rid, JoinRoomReply(2, 0x0001aaaabbbbcccc, rd, []MemberInfo{me, {No: 2, Name: "Joiner", Country: "gb", NAT: 2}}, tok, tok)...)
	for _, c := range []struct {
		name string
		got  []byte
		want string
	}{
		{"create", create, ""},
		{"join", join, ""},
	} {
		if hex.EncodeToString(c.got) != c.want {
			t.Errorf("%s reply changed:\n got %x\nwant %s", c.name, c.got, c.want)
		}
	}
}
